set-variable.value:
@{
        var response = context.Variables.GetValueOrDefault<IResponse>("routingRead", null);
        if (response == null || response.StatusCode != 200) { return "read-failed"; }
        var text = response.Body.As<string>(preserveContent: true);
        if (text != null) { text = text.TrimStart((char)65279); }
        if (String.IsNullOrWhiteSpace(text) || !text.TrimStart().StartsWith("{")) { return "invalid-routing-state"; }
        Newtonsoft.Json.Linq.JObject body;
        try { body = Newtonsoft.Json.Linq.JObject.Parse(text); }
        catch (Newtonsoft.Json.JsonReaderException) { return "invalid-routing-state"; }
        var properties = body["properties"] as Newtonsoft.Json.Linq.JObject;
        var active = properties == null ? "" : (string)properties["value"];
        if (active == "secondary-cu") { return "already-secondary"; }
        if (active != "primary-cu") { return "invalid-routing-state"; }
        return String.IsNullOrEmpty(response.Headers.GetValueOrDefault("ETag", "")) ? "missing-etag" : "eligible";
      }

@{
            var response = context.Variables.GetValueOrDefault<IResponse>("routingWrite", null);
            if (response == null) { return "write-outcome-unknown"; }
            if (response.StatusCode == 412) { return "conflict"; }
            return response.StatusCode == 200 || response.StatusCode == 202 ? "accepted-awaiting-activation" : "write-failed";
          }
